func testEntidadeToManySetOpEntEquipamentos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Entidade
	var b, c, d, e Equipamento

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, entidadeDBTypes, false, strmangle.SetComplement(entidadePrimaryKeyColumns, entidadeColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Equipamento{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, equipamentoDBTypes, false, strmangle.SetComplement(equipamentoPrimaryKeyColumns, equipamentoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err = a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.SetEntEquipamentos(ctx, tx, false, &b, &c)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.EntEquipamentos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	err = a.SetEntEquipamentos(ctx, tx, true, &d, &e)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.EntEquipamentos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.EntID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.EntID) {
		t.Error("want c's foreign key value to be nil")
	}
	if !queries.Equal(a.EntID, d.EntID) {
		t.Error("foreign key was wrong value", a.EntID, d.EntID)
	}
	if !queries.Equal(a.EntID, e.EntID) {
		t.Error("foreign key was wrong value", a.EntID, e.EntID)
	}

	if b.R.Ent != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Ent != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Ent != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}
	if e.R.Ent != &a {
		t.Error("relationship was not added properly to the foreign struct")
	}

	if a.R.EntEquipamentos[0] != &d {
		t.Error("relationship struct slice not set to correct value")
	}
	if a.R.EntEquipamentos[1] != &e {
		t.Error("relationship struct slice not set to correct value")
	}
}

